window.__CH("c15",["<div class=\"hw\">inēlabōrātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[in-<SUP>2</SUP>/elaboratus]</div><div class=\"def\"><num>①</num> 入念に仕上げられていない.</div><div class=\"def\"><num>②</num> 労せずして得た.</div>\r\n","<div class=\"hw\">inēlegans</div><div class=\"pos\">-antis, <i>adj</i></div><div class=\"ori\">[in-<SUP>2</SUP>/elegans]</div><div class=\"def\">優雅でない, 品のない, 洗練されていない.</div>\r\n","<div class=\"hw\">inēleganter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://inēlegans\">inēlegans</a>]</div><div class=\"def\">優雅でない様子で, 洗練されないで, ぎこちなく.</div>\r\n","<div class=\"hw\">inēlegantia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[inelegans]</div><div class=\"def\">法律の精密さに対する注意不足.</div>\r\n","<div class=\"hw\">inēluctābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[in-<SUP>2</SUP>/eluctabilis]</div><div class=\"def\">避け[のがれ]られない.</div>\r\n","<div class=\"hw\">inēmendābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[in-<SUP>2</SUP>/emendabilis]</div><div class=\"def\">矯正できない, 度しがたい.</div>\r\n","<div class=\"hw\">inēmorior</div><div class=\"pos\">-morī, <i>intr dep</i></div><div class=\"ori\">[in-<SUP>1</SUP>/emorior]</div><div class=\"def\">(...のまん中で)死ぬ 〈alci rei〉.</div>\r\n","<div class=\"hw\">inēmorī</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://inēmorior\">inemorior</a>.</div>\r\n","<div class=\"hw\">inēnarrābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[in-<SUP>2</SUP>/enarrabilis]</div><div class=\"def\">言い表わせない, 名状しがたい.</div>\r\n","<div class=\"hw\">inēnōdābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[in-<SUP>2</SUP>/enodo]</div><div class=\"def\"><num>①</num> ほどけない, もつれた.</div><div class=\"def\"><num>②</num> 説明[解明]できない.</div>\r\n","<div class=\"hw\">inērudītiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[in-<SUP>2</SUP>/eruditio]</div><div class=\"def\">無学.</div>\r\n","<div class=\"hw\">inērudītus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[in-<SUP>2</SUP>/eruditus]</div><div class=\"def\">無学の, 無知の.</div>\r\n","<div class=\"hw\">inērudītē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[ineruditus]</div><div class=\"def\">無知に;へたに.</div>\r\n","<div class=\"hw\">inēvectus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[in-<SUP>1</SUP>/eveho]</div><div class=\"def\">上方へ運ばれた.</div>\r\n","<div class=\"hw\">inēvītābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[in-<SUP>2</SUP>/evitabilis]</div><div class=\"def\">避けられない.</div>\r\n","<div class=\"hw\">inīcus<SUP>1, 2</SUP></div><div class=\"def\">=<a href=\"entry://inīquus\">iniquus<SUP>1</SUP></a>, <a href=\"entry://inīquus\">iniquus<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">inīquitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://inīquus\">inīquus<SUP>1</SUP></a>]</div><div class=\"def\"><num>①</num> 平坦でないこと, でこぼこ.</div><div class=\"def\"><num>②</num> 不平等, 不釣合い.</div><div class=\"def\"><num>③</num> 不公平, 不当.</div><div class=\"def\"><num>④</num> 不利, 不都合.</div>\r\n","<div class=\"hw\">inīquus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[in-<SUP>2</SUP>/aequus]</div><div class=\"def\"><num>①</num> でこぼこの, 平坦でない.</div><div class=\"def\"><num>②</num> 等しくない, 不釣合いの.</div><div class=\"def\"><num>③</num> 不利な, 不都合な.</div><div class=\"def\"><num>④</num> 過度の.</div><div class=\"def\"><num>⑤</num> 不公平な, 不当な.</div><div class=\"def\"><num>⑥</num> 敵意ある, 好意的でない 〈alci〉.</div><div class=\"def\"><num>⑦</num> 不満な, 不機嫌な.</div><hr><div class=\"hw\">inīquus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">敵, 他人の不幸を願う人.</div>\r\n","<div class=\"hw\">inīquē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[iniquus<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 不釣合いに.</div><div class=\"def\"><num>②</num> 不公平に, 不当に.</div><div class=\"def\"><num>③</num> 不機嫌に.</div>\r\n","<div class=\"hw\">inīre</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://ineō\">ineo</a>.</div>\r\n","<div class=\"hw\">inīvī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">=<a href=\"entry://iniī\">inii</a>(⇒ <a href=\"entry://ineō\">ineo</a>).</div>\r\n","<div class=\"hw\">inōminālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[in-<SUP>2</SUP>/omen]</div><div class=\"def\">凶兆の, 不吉な.</div>\r\n","<div class=\"hw\">inōminātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[in-<SUP>2</SUP>/omen]</div><div class=\"def\">凶兆の, 不吉な.</div>\r\n","<div class=\"hw\">inōrātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[in-<SUP>2</SUP>/oro]</div><div class=\"def\">(訴訟において)弁護されない, 申し開きの場を与えられない.</div>\r\n","<div class=\"hw\">inūber</div><div class=\"pos\">-ūberis, <i>adj</i></div><div class=\"ori\">[in-<SUP>2</SUP>/uber<SUP>2</SUP>]</div><div class=\"def\">やせた, 成育不良の.</div>\r\n","<div class=\"hw\">inūrō</div><div class=\"pos\">-ere -ussī -ustum, <i>tr</i></div><div class=\"ori\">[in-<SUP>1</SUP>/uro]</div><div class=\"def\"><num>①</num> 焼く, 焦がす.</div><div class=\"def\"><num>②</num> (髪を)こてでカールさせる.</div><div class=\"def\"><num>③</num> 焼き印を押す.</div><div class=\"def\"><num>④</num> 強く印象づける.</div><div class=\"def\"><num>⑤</num> (苦痛・恥辱・危害などを)負わせる, 課する.</div>\r\n","<div class=\"hw\">inūsitātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[in-<SUP>2</SUP>/usitatus]</div><div class=\"def\">異常な, 奇妙な.</div>\r\n","<div class=\"hw\">inūsitātē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://inūsitātus\">inūsitātus</a>]</div><div class=\"def\">異常に, 奇妙に.</div>\r\n","<div class=\"hw\">inūtilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[in-<SUP>2</SUP>/utilis]</div><div class=\"def\"><num>①</num> 役に立たない, 無用の.</div><div class=\"def\"><num>②</num> 不利な, 不便な.</div><div class=\"def\"><num>③</num> 有害な.</div>\r\n","<div class=\"hw\">inūtiliter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[inutilis]</div><div class=\"def\"><num>①</num> 無益に, 無用に.</div><div class=\"def\"><num>②</num> 不利に, 有害に.</div>\r\n","<div class=\"hw\">inūtilitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://inūtilis\">inūtilis</a>]</div><div class=\"def\"><num>①</num> 無用.</div><div class=\"def\"><num>②</num> 不利益.</div>\r\n","<div class=\"hw\">Iocasta</div><div class=\"pos\">-ae, <B>-ē</B> -ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙イオカスタ, <SUP>*</SUP>-テー《Thebae の王 Laius の妃で Oedipus の母;わが子と知らずに Oedipus の妃となった》.</div>\r\n","<div class=\"hw\">Iolāus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙イオラーウス, <SUP>*</SUP>-オス《Iphiclus の息子;Hercules の功業や遠征に常につき従った》.</div>\r\n","<div class=\"hw\">Iolē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙イオレー《Oechalia の王 Eurytus の娘;Hercules にとらえられ, 彼の息子 Hyllus の妻となった》.</div>\r\n","<div class=\"hw\">Ios, Ius</div><div class=\"pos\">Iī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">イオス《エーゲ海の Sporades 諸島の一つ;Homerus の埋葬地と伝えられる》.</div>\r\n","<div class=\"hw\">ipse</div><div class=\"pos\">-a -um(<i>sg gen</i> ips<img class=\"font\" src=\"img/A130.png\">us, <i>dat</i> ipsī(いずれも三性共通)), <i>pron intens</i></div><div class=\"ori\">[is/-pse(<i>cf</i>. -pte)]</div><div class=\"def\"><num>①</num> 自ら, 自身</div><div class=\"ex\">～ <i>dixit</i> (<author>C<small>IC</small></author>)<span class=\"ext\">(先生)自らがおっしゃった.</span></div><div class=\"def\"><num>②</num> ちょうど, まさに</div><div class=\"ex\"><i>in hunc ipsum locum</i> (<author>C<small>IC</small></author>)<span class=\"ext\">まさにこの場所へ</span></div><div class=\"ex\"><i>triennio ipso minor quam Antonius</i> (<author>C<small>IC</small></author>)<span class=\"ext\">Antonius よりもちょうど3年若い.</span></div><div class=\"def\"><num>③</num> 自発的に, 自ら進んで.</div><div class=\"def\"><num>④</num> ～ <i>quoque</i>=<i>et</i> ～ 同様に...も, ...もまた</div><div class=\"ex\"><i>natus et</i> ～ <i>deā</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">彼自身もまた女神から生まれた.</span></div><div class=\"def\"><num>⑤</num> </div><div class=\"ex\">(喜劇中の <i>superl</i>)<i>ipsissimus</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">正真正銘の本人だ.</span></div>\r\n","<div class=\"hw\">ircus, ▶etc.◀</div><div class=\"def\">⇒<a href=\"entry://hircus\">hircus</a>, etc.</div>\r\n","<div class=\"hw\">irpex</div><div class=\"pos\">-picis, <i>m</i></div><div class=\"def\">鉄歯の熊手.</div>\r\n","<div class=\"hw\">Irpīnī, ▶etc.◀</div><div class=\"def\">⇒<a href=\"entry://Hirpīnī\">Hirpini</a>, etc.</div>\r\n","<div class=\"hw\">irradiātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[irradio]</div><div class=\"def\">照らすこと, 照射.</div>\r\n","<div class=\"hw\">irradiātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://irradiō\">irradio</a>.</div>\r\n","<div class=\"hw\">irradiō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i>, <i>intr</i></div><div class=\"ori\">[in-<SUP>1</SUP>/radio]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>tr</i>)(...に)光を投ずる, 照らす 〈alqd〉.</div><div class=\"def\"><num0>Ⅱ</num0> <SUP>◇</SUP>(<i>intr</i>)夜が明ける.</div>\r\n","<div class=\"hw\">irratiōnābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">=<a href=\"entry://irratiōnālis\">irrationalis</a>.</div>\r\n","<div class=\"hw\">irratiōnālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[in-<SUP>2</SUP>/rationalis]</div><div class=\"def\">理性のない;不合理な.</div>\r\n","<div class=\"hw\">irratiōnāliter</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://irratiōnālis\">irratiōnālis</a>]</div><div class=\"def\">不合理に.</div>\r\n","<div class=\"hw\">irraucescō</div><div class=\"pos\">-ere -rausī, <i>intr</i></div><div class=\"ori\">[in-<SUP>1</SUP>/raucus]</div><div class=\"def\">声がかれる, しゃがれ声になる.</div>\r\n","<div class=\"hw\">irrausī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://irraucescō\">irraucesco</a>.</div>\r\n","<div class=\"hw\">irrecuperābilis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[in-<SUP>2</SUP>/recupero]</div><div class=\"def\">取り返せない, 回復できない.</div>\r\n","<div class=\"hw\">irrefrāgābilis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[in-<SUP>2</SUP>/refragor]</div><div class=\"def\">論駁できない, 論争の余地のない.</div>\r\n","<div class=\"hw\">irreligiōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[in-<SUP>2</SUP>/religiosus<SUP>1</SUP>]</div><div class=\"def\">不信心な, 冒涜的な.</div>\r\n","<div class=\"hw\">irreligiōsē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://irreligiōsus\">irreligiōsus</a>]</div><div class=\"def\">不信心に, 冒涜的に.</div>\r\n","<div class=\"hw\">irreligātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[in-<SUP>2</SUP>/religo]</div><div class=\"def\"><num>①</num> (髪が)束ねられていない.</div><div class=\"def\"><num>②</num> (船が)つなぎとめられていない.</div>\r\n","<div class=\"hw\">irremediābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[in-<SUP>2</SUP>/remediabilis]</div><div class=\"def\">治療できない, 不治の, 致命的な.</div>\r\n","<div class=\"hw\">irremeābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[in-<SUP>2</SUP>/remeabilis]</div><div class=\"def\">引き返せない, 戻れない.</div>\r\n","<div class=\"hw\">irremissus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[in-<SUP>2</SUP>/remitto]</div><div class=\"def\">容赦しない, ゆるめることのない.</div>\r\n","<div class=\"hw\">irremissē</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://irremissus\">irremissus</a>]</div><div class=\"def\">容赦なく.</div>\r\n","<div class=\"hw\">irreparābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[in-<SUP>2</SUP>/reparabilis]</div><div class=\"def\">取り返せない, 回復できない.</div>\r\n","<div class=\"hw\">irrepertus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[in-<SUP>2</SUP>/reperio]</div><div class=\"def\">見つけられていない, 未発見の.</div>\r\n","<div class=\"hw\">irreprehensibilis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[in-<SUP>2</SUP>/reprehensibilis]</div><div class=\"def\">非難の余地のない, 申し分のない.</div>\r\n","<div class=\"hw\">irreprehensibiliter</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://irreprehensibilis\">irreprehensibilis</a>]</div><div class=\"def\">非難の余地なく, 申し分なく.</div>\r\n","<div class=\"hw\">irreprehensus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[in-<SUP>2</SUP>/reprehendo]</div><div class=\"def\">非難されていない, 罪のない.</div>\r\n","<div class=\"hw\">irrepsī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://irrēpō\">irrepo</a>.</div>\r\n","<div class=\"hw\">irreptus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://irrēpō\">irrepo</a>.</div>\r\n","<div class=\"hw\">irrequiētus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[in-<SUP>2</SUP>/requietus]</div><div class=\"def\">休まない, 疲れを知らない;絶え間ない.</div>\r\n","<div class=\"hw\">irresectus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[in-<SUP>2</SUP>/reseco]</div><div class=\"def\">(爪が)切られていない.</div>\r\n","<div class=\"hw\">irresolūtus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[in-<SUP>2</SUP>/resolvo]</div><div class=\"def\">ゆるめられて[ほどけて]いない.</div>\r\n","<div class=\"hw\">irretortus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[in-<SUP>2</SUP>/retorqueo]</div><div class=\"def\">(目が)後ろへ振り向けられていない.</div>\r\n","<div class=\"hw\">irreverens</div><div class=\"pos\">-entis, <i>adj</i></div><div class=\"ori\">[in-<SUP>2</SUP>/reverens]</div><div class=\"def\">不敬な, 無礼な.</div>\r\n","<div class=\"hw\">irreverenter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://irreverens\">irreverens</a>]</div><div class=\"def\">不敬に, 無礼に.</div>\r\n","<div class=\"hw\">irreverentia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[irreverens]</div><div class=\"def\">不敬, 無礼.</div>\r\n","<div class=\"hw\">irrevocābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[in-<SUP>2</SUP>/revocabilis]</div><div class=\"def\"><num>①</num> 呼び戻せない;取り返せない, 取り消せない.</div><div class=\"def\"><num>②</num> 引き留められない.</div>\r\n","<div class=\"hw\">irrevocātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[in-<SUP>2</SUP>/revoco]</div><div class=\"def\"><num>①</num> アンコールを所望されていない.</div><div class=\"def\"><num>②</num> 引き留められない.</div>\r\n","<div class=\"hw\">irriguus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://irrigō\">irrigō</a>]</div><div class=\"def\"><num>①</num> 灌漑された;潤された.</div><div class=\"def\"><num>②</num> 灌漑する, 潤す.</div><div class=\"def\"><num>③</num> 酒浸りの.</div>\r\n","<div class=\"hw\">irrigātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[irrigo]</div><div class=\"def\">灌水, 灌漑.</div>\r\n","<div class=\"hw\">irrigātor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[↓<a href=\"entry://irrigō\">irrigō</a>]</div><div class=\"def\">灌漑する人.</div>\r\n","<div class=\"hw\">irrigō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[in-<SUP>1</SUP>/rigo]</div><div class=\"def\"><num>①</num> (水を)引く 〈alqd in alqd〉.</div><div class=\"def\"><num>②</num> 灌水[灌漑]する, 浸す, 潤す.</div><div class=\"def\"><num>③</num> 活気づける, 養う</div><div class=\"ex\"><i>irrigare vino aetatem</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">ぶどう酒で若さを元気づける.</span></div>\r\n","<div class=\"hw\">irritatiō<SUP>2</SUP></div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[irrito<SUP>2</SUP>]</div><div class=\"def\">取消し, 失効.</div>\r\n","<div class=\"hw\">irritum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://irritus\">irritus</a>]</div><div class=\"def\">無, 無価値.</div>\r\n","<div class=\"hw\">irritus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[in-<SUP>2</SUP>/ratus]</div><div class=\"def\"><num>①</num> 無効の, 取り消された.</div><div class=\"def\"><num>②</num> 無益な, むだな, むなしい.</div><div class=\"def\"><num>③</num> 望みが果たせなかった, 挫折した 〈+<i>gen</i>〉.</div>\r\n","<div class=\"hw\">irritō<SUP>2</SUP></div><div class=\"pos\">-āre -āvī -ātum, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[irritus]</div><div class=\"def\">無効にする.</div>\r\n","<div class=\"hw\">irrogātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://irrogō\">irrogō</a>]</div><div class=\"def\"><num>①</num> (処罰の)要求.</div><div class=\"def\"><num>②</num> (罰を)課すること.</div>\r\n","<div class=\"hw\">irrogō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[in-<SUP>1</SUP>/rogo]</div><div class=\"def\"><num>①</num> (処罰・科料を)提案[要求]する.</div><div class=\"def\"><num>②</num> (処罰・危害などを)課する, 負わせる 〈alci alqd〉.</div>\r\n","<div class=\"hw\">irrubescō</div><div class=\"pos\">-ere -rubuī, <i>intr</i></div><div class=\"ori\">[in-<SUP>1</SUP>/rubesco]</div><div class=\"def\">赤くなる, 赤く輝く.</div>\r\n","<div class=\"hw\">irrubuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://irrubescō\">irrubesco</a>.</div>\r\n","<div class=\"hw\">irructō</div><div class=\"pos\">-āre, <i>intr</i></div><div class=\"ori\">[in-<SUP>1</SUP>/ructo]</div><div class=\"def\">(...に向かって)げっぷをする 〈alci in os〉.</div>\r\n","<div class=\"hw\">irrugiī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://irrugiō\">irrugio</a>.</div>\r\n","<div class=\"hw\">irrugiō</div><div class=\"pos\">-īre -rugiī, <SUP>◇</SUP><i>intr</i></div><div class=\"ori\">[in-<SUP>1</SUP>/rugio]</div><div class=\"def\">大声で叫ぶ.</div>\r\n","<div class=\"hw\">irrumpō</div><div class=\"pos\">-ere -rūpī -ruptum, <i>intr</i>, <i>tr</i></div><div class=\"ori\">[in-<SUP>1</SUP>/rumpo]</div><div class=\"def\"><num>①</num> 押し入る, 突入する, 侵入する 〈in alqd;alci rei;alqd〉.</div><div class=\"def\"><num>②</num> (心に)入り込む;(人・心を)襲う.</div>\r\n","<div class=\"hw\">irrumātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[irrumo]</div><div class=\"def\">吸茎(=<a href=\"entry://fellātiō\">fellatio</a>).</div>\r\n","<div class=\"hw\">irrumātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[↓<a href=\"entry://irrumō\">irrumō</a>]</div><div class=\"def\">吸茎をさせる者.</div>\r\n","<div class=\"hw\">irrumō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"def\">吸茎をさせる.</div>\r\n","<div class=\"hw\">irruptiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[irrumpo]</div><div class=\"def\"><num>①</num> 乱入, 突入.</div><div class=\"def\"><num>②</num> 襲撃, 侵入.</div>\r\n","<div class=\"hw\">irruptus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://irrumpō\">irrumpo</a>.</div><hr><div class=\"hw\">irruptus<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[in-<SUP>2</SUP>/rumpo]</div><div class=\"def\">切り離されていない, こわれていない.</div>\r\n","<div class=\"hw\">irruō</div><div class=\"pos\">-ere -ruī, <i>intr</i>(<i>tr</i>)</div><div class=\"ori\">[in-<SUP>1</SUP>/ruo]</div><div class=\"def\"><num>①</num> 飛び込む, 突入する 〈in alqd〉.</div><div class=\"def\"><num>②</num> 襲いかかる, 攻撃する.</div>\r\n","<div class=\"hw\">irrāsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[in-<SUP>2</SUP>/rado]</div><div class=\"def\"><num>①</num> (ひげ・髪が)そられていない.</div><div class=\"def\"><num>②</num> 磨いていない, ざらざらの.</div>\r\n","<div class=\"hw\">irrēgulāris</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[in-<SUP>2</SUP>/reguralis<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 不規則な, 異例の, 変則の.</div><div class=\"def\"><num>②</num> 〘カト〙不適格の.</div>\r\n","<div class=\"hw\">irrēgulāritās</div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↑<a href=\"entry://irrēgulāris\">irrēgulāris</a>]</div><div class=\"def\">〘カト〙(叙階の)不適格.</div>\r\n","<div class=\"hw\">irrēpō</div><div class=\"pos\">-ere -repsī -reptum, <i>intr</i>(<i>tr</i>)</div><div class=\"ori\">[in-<SUP>1</SUP>/repo]</div><div class=\"def\"><num>①</num> はって行く, のろのろ行く 〈ad [in] alqd;alci rei〉.</div><div class=\"def\"><num>②</num> (徐々に)入り込む, 忍び込む 〈in alqd;alci rei〉.</div>\r\n","<div class=\"hw\">irrētiō</div><div class=\"pos\">-īre -īvī [-iī] -ītum, <i>tr</i></div><div class=\"ori\">[in-<SUP>1</SUP>/rete]</div><div class=\"def\"><num>①</num> 網で捕える, わなにかける.</div><div class=\"def\"><num>②</num> (誘惑・困難などに)陥れる, 巻き込む 〈alqm re〉</div><div class=\"ex\"><i>irretire se erratis</i> (<author>C<small>IC</small></author>)<span class=\"ext\">自らを過ちに巻き込む.</span></div>\r\n","<div class=\"hw\">irrētītus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://irrētiō\">irretio</a>.</div>\r\n","<div class=\"hw\">irrīdeō</div><div class=\"pos\">-ēre -rīsī -rīsum, <i>intr</i>, <i>tr</i></div><div class=\"ori\">[in-<SUP>1</SUP>/rideo]</div><div class=\"def\">あざける, ばかにする 〈in re;+<i>dat</i>;alqm [alqd]〉.</div>\r\n","<div class=\"hw\">irrīdiculum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://irrīdiculus\">irrīdiculus</a>]</div><div class=\"def\">笑い草, 物笑いの種.</div>\r\n","<div class=\"hw\">irrīdiculus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[irrideo]</div><div class=\"def\">笑うべき, 滑稽な, おかしな.</div>\r\n","<div class=\"hw\">irrīdiculē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[in-<SUP>2</SUP>/ridicule]</div><div class=\"def\">機知に富まないで.</div>\r\n","<div class=\"hw\">irrīsiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"def\">=<a href=\"entry://irrīsus\">irrisus<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">irrīsor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[irrideo]</div><div class=\"def\">嘲笑者, あざける者.</div>\r\n","<div class=\"hw\">irrīsus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://irrīdeō\">irrideo</a>.</div><hr><div class=\"hw\">irrīsus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\">嘲笑, あざけり.</div>\r\n","<div class=\"hw\">irrīsī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://irrīdeō\">irrideo</a>.</div>\r\n","<div class=\"hw\">irrītābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[irrito<SUP>1</SUP>]</div><div class=\"def\">怒りっぽい, 短気な.</div>\r\n","<div class=\"hw\">irrītāmen</div><div class=\"pos\">-minis, <i>n</i></div><div class=\"ori\">[irrito<SUP>1</SUP>]</div><div class=\"def\">刺激, 挑発, 誘惑.</div>\r\n","<div class=\"hw\">irrītāmentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">=<a href=\"entry://irrītāmen\">irritamen</a>.</div>\r\n","<div class=\"hw\">irrītātiō<SUP>1</SUP></div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[irrito<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 刺激.</div><div class=\"def\"><num>②</num> 怒らせること.</div>\r\n","<div class=\"hw\">irrītātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[irrito<SUP>1</SUP>]</div><div class=\"def\">刺激する人.</div>\r\n","<div class=\"hw\">irrītātrix</div><div class=\"pos\">-īcis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://irrītātor\">irrītātor</a>]</div><div class=\"def\">刺激する人《女性》.</div>\r\n","<div class=\"hw\">irrītō<SUP>1</SUP></div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"def\"><num>①</num> 怒らせる, いら立たせる.</div><div class=\"def\"><num>②</num> 駆りたてる 〈alqm [alqd] ad [in] alqd〉.</div><div class=\"def\"><num>③</num> かきたてる, あおる;ひき起こす.</div><div class=\"def\"><num>④</num> 悪化させる.</div>\r\n","<div class=\"hw\">irrōrō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i>, <i>intr</i></div><div class=\"ori\">[in-<SUP>1</SUP>/roro]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>tr</i>)</div><div class=\"def\"><num>①</num> 湿らす, ぬらす 〈alqd〉.</div><div class=\"def\"><num>②</num> 注ぐ, 振りかける 〈alci rei alqd〉.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>intr</i>)</div><div class=\"def\"><num>①</num> したたる 〈alci rei〉.</div>\r\n","<div class=\"hw\">irrūgō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[in-<SUP>1</SUP>/rugo]</div><div class=\"def\">しわを寄せる.</div>\r\n","<div class=\"hw\">irrūpī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://irrumpō\">irrumpo</a>.</div>\r\n","<div class=\"hw\">is</div><div class=\"pos\">ea id, <i>pron</i>, <i>adj demonstr</i></div><div class=\"def\"><num>①</num> 彼, 彼女, それ.</div><div class=\"def\"><num>②</num> ～, <i>qui</i> ...の人</div><div class=\"ex\"><i>ii</i>, <i>qui multa ventorum nomina noverunt</i> (<author>V<small>ITR</small></author>)<span class=\"ext\">風の多くの名前を知っている人々.</span></div><div class=\"def\"><num>③</num> この, その.</div><div class=\"def\"><num>④</num> この[その]ような.</div><div class=\"def\"><num>⑤</num> (単独で)そのために</div><div class=\"ex\"><i>id gaudeo</i> (<author>C<small>IC</small></author>)<span class=\"ext\">そのために私は喜んでいる.</span></div><div class=\"def\"><num>⑥</num> 〈+<i>gen</i>〉</div><div class=\"ex\"><i>id temporis</i> [<i>diei</i>] (<author>C<small>IC</small> [G<small>ELL</small>]</author>)<span class=\"ext\">(一日の)その時刻(に)</span></div><div class=\"ex\"><i>id aetatis</i> (<author>C<small>IC</small></author>)<span class=\"ext\">その年頃の</span></div><div class=\"ex\"><i>in eo esse</i>, <i>ut</i><span class=\"ext\">(まさに)...しようとしている</span></div><div class=\"ex\"><i>cum jam in eo esset</i>, <i>ut oppido potiretur</i> (<author>N<small>EP</small></author>)<span class=\"ext\">彼がまさに町を占領しかかったとき</span></div><div class=\"ex\"><i>id est</i> (<author>C<small>IC</small></author>)<span class=\"ext\">すなわち</span></div><div class=\"ex\"><i>et</i> ～ = ～<i>que</i><span class=\"ext\">そして...もまた, しかもそのうえ</span></div><div class=\"ex\"><i>vincula</i>, <i>et ea sempiterna</i> (<author>C<small>IC</small></author>)<span class=\"ext\">拘束, しかも永遠のそれ</span></div><div class=\"ex\"><i>cum hoc decertandum est</i>, <i>idque confestim</i> (<author>C<small>IC</small></author>)<span class=\"ext\">この男と戦わねばならぬ, しかもそれは即刻にだ.</span></div>\r\n","<div class=\"hw\">Isaacus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">=<a href=\"entry://Isaāc\">Isaac</a>.</div>\r\n","<div class=\"hw\">Isara</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">イサラ《Gallia の川;Rhodanus 川に注ぐ;現 Isère》.</div>\r\n","<div class=\"hw\">Isauria</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">イサウリア(ー)《小アジアの Pisidia と Lycaonia の間の地域》.</div>\r\n","<div class=\"hw\">Isauricus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Isauria の.</div>\r\n","<div class=\"hw\">Isaurus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Isauricus\">Isauricus</a>.</div><hr><div class=\"hw\">Isaurus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">イサウルス《Picenum の川》.</div>\r\n","<div class=\"hw\">Isaurī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">Isauria の住民.</div>\r\n","<div class=\"hw\">Isaāc</div><div class=\"pos\"><i>indecl</i><SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Heb</i>.]</div><div class=\"def\">〘聖〙イサアーク, <SUP>∥</SUP>イサク《Abraham と Sara の息子で Jacob の父》.</div>\r\n","<div class=\"hw\">ischaemia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙虚血, 乏血.</div>\r\n","<div class=\"hw\">ischia</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘解〙臀部(=coxae).</div>\r\n","<div class=\"hw\">ischiadicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘解〙坐骨神経痛の.</div>\r\n","<div class=\"hw\">ischias</div><div class=\"pos\">-adis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘病〙坐骨神経痛(=<a href=\"entry://sciatica\">sciatica</a>).</div>\r\n","<div class=\"hw\">ischnos</div><div class=\"pos\">-ē -on, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ほっそりした.</div>\r\n","<div class=\"hw\">Ischomachē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"def\">=<a href=\"entry://Hippodamīa\">Hippodamia (2)</a> .</div>\r\n","<div class=\"hw\">Isiondensēs</div><div class=\"pos\">-ium, <i>m pl</i></div><div class=\"def\">Pisidia 南西部の町 Isionda の住民.</div>\r\n","<div class=\"hw\">Ismara</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"def\">=<a href=\"entry://Ismarus\">Ismarus</a>.</div>\r\n","<div class=\"hw\">Ismarius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Ismarus の;Thracia の.</div>\r\n","<div class=\"hw\">Ismarus</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">イスマルス, <SUP>*</SUP>-ロス《Thracia 南部の山と町》.</div>\r\n","<div class=\"hw\">Ismēnis</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"def\">Ismenus(=<a href=\"entry://Thēbae\">Thebae</a>)の女.</div>\r\n","<div class=\"hw\">Ismēnius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Ismenus 川の;Thebae の.</div>\r\n","<div class=\"hw\">Ismēniās</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">イスメーニアース《 (1) Thebae の著名な笛吹き.(2) Boeotia の将軍》.</div>\r\n","<div class=\"hw\">Ismēnus, -os</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">イスメーヌス, <SUP>*</SUP>-ノス《Boeotia の Thebae 付近を流れる川》.</div>\r\n","<div class=\"hw\">Ismēnē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙イスメーネー《Oedipus と Iocasta の娘》.</div>\r\n","<div class=\"hw\">Isrāēl</div><div class=\"pos\">-ēlis または <i>indecl</i><SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i><<i>Heb</i>.]</div><div class=\"def\">〘聖〙イスラーエール《 (1) Jacob の異名.(2) Jacob の子孫の呼称;ユダヤ人》.</div>\r\n","<div class=\"hw\">Isrāēlītae</div><div class=\"pos\">-ōrum, <SUP>◇</SUP><i>m pl</i></div><div class=\"ori\">[↑<a href=\"entry://Isrāēl\">Isrāēl</a>]</div><div class=\"def\">〘聖〙Jacob の子孫, ユダヤ人.</div>\r\n","<div class=\"hw\">Issa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">イッサ《アドリア海の島》.</div>\r\n","<div class=\"hw\">Issaeus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Issa 島の.</div><div class=\"hw2\"><b>Issaeī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Issa 島の住民.</div>\r\n","<div class=\"hw\">Issaicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Issaeus\">Issaeus</a>.</div>\r\n","<div class=\"hw\">Issensis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Issaeus\">Issaeus</a>.</div><div class=\"hw2\"><b>Issensēs</b></div><div class=\"pos2\">-ium, <i>m pl</i></div><div class=\"def2\">=<a href=\"entry://Issaeus\">Issaei</a>.</div>\r\n","<div class=\"hw\">Issus, -os</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">イッスス, <SUP>*</SUP>-ソス《Cilicia の町;Amanus 山麓にあり, この地で Persia 王 Dareus III が Alexander 大王に大敗した(前333)》.</div>\r\n","<div class=\"hw\">istactenus</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://istāc\">istāc</a>/tenus<SUP>2</SUP>]</div><div class=\"def\">そこまで.</div>\r\n","<div class=\"hw\">Istaevonēs</div><div class=\"pos\">-um, <i>m pl</i></div><div class=\"def\">イスタエウォネース《Rhenus 河畔にいたゲルマン系一部族》.</div>\r\n","<div class=\"hw\">iste</div><div class=\"pos\">-a -ud, <i>pron</i>, <i>adj demonstr</i></div><div class=\"def\"><num>①</num> あの, その, かの;(あなたの知っている;あなたが言うところの)その.</div><div class=\"def\"><num>②</num> そのような.</div><div class=\"def\"><num>③</num> あれ, それ.</div><div class=\"def\"><num>④</num> (軽蔑的に)そんな.</div><div class=\"def\"><num>⑤</num> (法廷で告発者が被告を指して)かかる(嘆かわしい[卑劣な]人物).</div>\r\n","<div class=\"hw\">Ister</div><div class=\"pos\">-trī, <i>m</i></div><div class=\"def\">=<a href=\"entry://Hister\">Hister</a>.</div>\r\n","<div class=\"hw\">Isthmia</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">イストミア祭《Corinthus で隔年に行なわれた大競技祭》.</div>\r\n","<div class=\"hw\">Isthmiacus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> Corinthus 地峡の;Corinthus の.</div><div class=\"def\"><num>②</num> Isthmia 大競技祭の.</div>\r\n","<div class=\"hw\">Isthmius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">=<a href=\"entry://Isthmiacus\">Isthmiacus</a>.</div>\r\n","<div class=\"hw\">isthmus, -os</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 地峡;(特に)Corinthus 地峡.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘解・動〙峡.</div>\r\n","<div class=\"hw\">istic<SUP>1</SUP></div><div class=\"pos\">-aec -oc [-uc], <i>pron</i>, <i>adj demonstr</i></div><div class=\"ori\">[iste/-ce]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>adj</i>)(あなたが言うところの)その.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>pron</i>)(あなたが言うところの)それ</div><div class=\"ex\"><i>istōc</i>(<i>n sg abl</i>)(<author>P<small>LAUT</small></author>)<span class=\"ext\">(あなたが言う)その理由によって.</span></div>\r\n","<div class=\"hw\">istim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[iste]</div><div class=\"def\">(あなたのいる)そこから.</div>\r\n","<div class=\"hw\">istinc</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://istim\">istim</a>/-ce]</div><div class=\"def\"><num>①</num> (あなたのいる)そこから.</div><div class=\"def\"><num>②</num> そのことから, その(ことの)うちの.</div>\r\n","<div class=\"hw\">istorsum</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[isto/versum]</div><div class=\"def\">(あなたのいる)そちらの方へ.</div>\r\n","<div class=\"hw\">Istrī, Istria, Istriānī</div><div class=\"def\">⇒<a href=\"entry://Histrī\">Histri</a>, <a href=\"entry://Histria\">Histria</a>, <a href=\"entry://Histriānī\">Histriani</a>.</div>\r\n","<div class=\"hw\">istuc<SUP>1</SUP></div><div class=\"pos\"><i>neut</i></div><div class=\"def\">⇒<a href=\"entry://istic\">istic<SUP>1</SUP></a>.</div>\r\n","<div class=\"hw\">istāc</div><div class=\"pos\"><i>adv</i>(<i>abl</i>)</div><div class=\"ori\">[istic<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> その道を通って.</div><div class=\"def\"><num>②</num> その方法で.</div>\r\n","<div class=\"hw\">istī</div><div class=\"pos\"><i>adv</i>(<i>sg loc</i>)</div><div class=\"ori\">[iste]</div><div class=\"def\">=<a href=\"entry://istīc\">istic<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">istīc<SUP>2</SUP></div><div class=\"pos\"><i>adv</i>(古い <i>loc</i>)</div><div class=\"ori\">[↑<a href=\"entry://istic\">istic<SUP>1</SUP></a>]</div><div class=\"def\"><num>①</num> そこに, あそこに.</div><div class=\"def\"><num>②</num> その中に, その点で</div><div class=\"ex\">～ <i>sum</i> (<author>T<small>ER</small></author>)<span class=\"ext\">私は(あなたのことばに)一心に耳を傾けている.</span></div>\r\n","<div class=\"hw\">istīusmodī</div><div class=\"pos\"><i>adj</i>(<i>gen</i>)</div><div class=\"ori\">[iste/modus]</div><div class=\"def\">そのような.</div>\r\n","<div class=\"hw\">istō</div><div class=\"pos\"><i>adv</i>(<i>sg abl</i>)</div><div class=\"ori\">[iste]</div><div class=\"def\"><num>①</num> (あなたのいる)そこへ.</div><div class=\"def\"><num>②</num> それへ.</div>\r\n","<div class=\"hw\">istōc</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[istic<SUP>1</SUP>]</div><div class=\"def\">(あなたのいる)そこへ.</div>\r\n","<div class=\"hw\">istūc<SUP>2</SUP></div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[istic<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> (あなたがいる)そこへ, そちらへ.</div><div class=\"def\"><num>②</num> (あなたが言う)その点へ.</div>\r\n","<div class=\"hw\">ita</div><div class=\"pos\"><i>adv</i></div><div class=\"def\"><num>①</num> この[その]ように</div><div class=\"ex\">～ <i>sum</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">(私は)そのとおりです</span></div><div class=\"ex\"><i>quam cum</i> ～ <i>sint</i> (<author>C<small>IC</small></author>)<span class=\"ext\">こういう訳だから.</span></div><div class=\"def\"><num>②</num> (肯定の答え)しかり</div><div class=\"ex\">～ <i>plane</i> [<i>prorsus</i>] (<author>C<small>IC</small></author>)<span class=\"ext\">全くそのとおり</span></div><div class=\"ex\"><i>non est</i> ～ (<author>C<small>IC</small></author>)<span class=\"ext\">さにあらず.</span></div><div class=\"def\"><num>③</num> (驚き・不信・皮肉を込めた疑問)本当にそうなのか?</div><div class=\"ex\">～<i>ne vero?</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">本当にそうかね?</span></div><div class=\"def\"><num>④</num> それゆえ</div><div class=\"ex\">～, <i>quicquid honestum</i>, <i>id utile</i> (<author>C<small>IC</small></author>)<span class=\"ext\">従って正当なことは何であれ有益だ.</span></div><div class=\"def\"><num>⑤</num> (程度)それほど, そんなに</div><div class=\"ex\"><i>quid</i> ～ <i>Nilus aestivis mensibus abundet</i> (<author>S<small>EN</small></author>)<span class=\"ext\">Nilus 川は夏期になぜそれほど氾濫するのか.</span></div><div class=\"def\"><num>⑥</num> (ut, quomodo, quemadmodum などとともに)...と同様に, ...のように</div><div class=\"ex\">～ <i>vero</i>, <i>ut precamini</i>, <i>eveniat</i> (<author>C<small>IC</small></author>)<span class=\"ext\">諸君の願いどおりの事態になってほしいものだ.</span></div><div class=\"def\"><num>⑦</num> (quasi, tamquam とともに)あたかも...のように</div><div class=\"ex\">～ <i>assimulatote quasi ego sim peregrinus</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">あたかも私が外国人であるかのように見せかけておくれ.</span></div><div class=\"def\"><num>⑧</num> (ut とともに)誓って</div><div class=\"ex\">～ <i>vivam</i>, <i>ut maximos sumptūs facio</i> (<author>C<small>IC</small></author>)<span class=\"ext\">生命にかけて, 私は途方もない金額を支出している</span></div><div class=\"ex\">(ut なしに)～ <i>me di ament</i>, <i>honestus est</i> (<author>T<small>ER</small></author>)<span class=\"ext\">神々にかけて(=本当に), すてきな人だわ.</span></div><div class=\"def\"><num>⑨</num> (傾向・結果を表わす ut 節とともに)...ので(その結果), ...それほど</div><div class=\"ex\"><i>sunt</i> ～ <i>multi ut eos carcer capere non possit</i> (<author>C<small>IC</small></author>)<span class=\"ext\">悪人どもは牢獄が彼らを収容できないほど数多い.</span></div><div class=\"def\"><num>⑩</num> (条件を表わす ut 節とともに)...の条件で, ...の限りで</div><div class=\"ex\"><i>pax</i> ～ <i>convenerat</i>, <i>ut Etruscis Latinisque fluvius Albula finis esset</i> (<author>L<small>IV</small></author>)<span class=\"ext\">Albula(=<a href=\"entry://Tiberis\">Tiberis</a>)川が Etruria 人と Latini 族の境界となるという条件で和議が成立していた.</span></div><div class=\"def\"><num>⑪</num> (目的を表わす ut 節とともに)...するように</div><div class=\"ex\">～, <i>ut ea res prosit rei publicae</i> (<author>C<small>IC</small></author>)<span class=\"ext\">そのことが国家のためになるように.</span></div>\r\n","<div class=\"hw\">Italia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">(語頭の i は hexameter 中で長音)イタリア.</div>\r\n","<div class=\"hw\">Italica</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">イタリカ《 (1) 同盟市戦争(前90‐88)の際, Corfinium に付けられた名.(2) Hispania Baetica の町;Trajanus 帝, Hadrianus 帝の生地》.</div>\r\n","<div class=\"hw\">Italicensēs</div><div class=\"pos\">-ium, <i>m pl</i></div><div class=\"def\">Italica (2) の住民.</div>\r\n","<div class=\"hw\">Italicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">(語頭の i は hexameter 中で長音)イタリアの, イタリア人の.</div>\r\n","<div class=\"hw\">Italis</div><div class=\"pos\">-idis [-idos], <i>f</i></div><div class=\"def\">(語頭の i は韻文中で長音)イタリアの女.</div>\r\n","<div class=\"hw\">Italus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">(語頭の i は韻文中でときに長音)イタリアの, イタリア人の.</div><hr><div class=\"hw\">Italus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">イタリア人.</div><hr><div class=\"hw\">Italus<SUP>3</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">イタルス《Italia の名祖である伝説的な王》.</div>\r\n","<div class=\"hw\">itaque</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[ita/-que<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> (=et ita)そしてこのように.</div><div class=\"def\"><num>②</num> 従って, それゆえに.</div>\r\n","<div class=\"hw\">item</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[<i>cf. </i> ita]</div><div class=\"def\"><num>①</num> 同じく, 同様に.</div><div class=\"def\"><num>②</num> また, さらに, そのうえ.</div>\r\n","<div class=\"hw\">iter</div><div class=\"pos\">itineris, <i>n</i></div><div class=\"ori\">[eo<SUP>2</SUP>;<i>cf. </i> itio]</div><div class=\"def\"><num>①</num> 旅, 旅行</div><div class=\"ex\">～ <i>facere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">旅をする</span></div><div class=\"ex\"><i>in itinere</i> (<author>T<small>ER</small></author>)<span class=\"ext\">道中で.</span></div><div class=\"def\"><num>②</num> 道.</div><div class=\"def\"><num>③</num> 行くこと, 歩行.</div><div class=\"def\"><num>④</num> 〘軍〙行進, 行軍</div><div class=\"ex\"><i>magnis itineribus</i> (<author>C<small>AES</small></author>)<span class=\"ext\">強行軍で.</span></div><div class=\"def\"><num>⑤</num> 行程.</div><div class=\"def\"><num>⑥</num> 通行権.</div><div class=\"def\"><num>⑦</num> 進路, 行路.</div><div class=\"def\"><num>⑧</num> 〘解〙(人体内の)管.</div><div class=\"def\"><num>⑨</num> 手段, 方法.</div><div class=\"def\"><num>⑩</num> 継続, 続行.</div>\r\n","<div class=\"hw\">iterum</div><div class=\"pos\"><i>adv</i></div><div class=\"def\"><num>①</num> 再び, もう一度</div><div class=\"ex\"><i>semel atque</i> ～ (<author>C<small>AES</small></author>) =<i>semel</i> ～<i>que</i> (<author>C<small>IC</small></author>) = ～ <i>atque</i> ～ (<author>H<small>OR</small></author>)<span class=\"ext\">繰り返して, 何度も.</span></div><div class=\"def\"><num>②</num> 他方では, これに反して.</div>\r\n","<div class=\"hw\">iterātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[itero]</div><div class=\"def\"><num>①</num> 繰返し, 反復.</div><div class=\"def\"><num>②</num> 再耕, 鋤き返し[直し].</div>\r\n","<div class=\"hw\">iterātō</div><div class=\"pos\"><i>adv</i>(<i>abl</i>)</div><div class=\"ori\">[↓<a href=\"entry://iterō\">iterō</a>]</div><div class=\"def\">再び, もう一度.</div>\r\n","<div class=\"hw\">iterō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://iterum\">iterum</a>]</div><div class=\"def\"><num>①</num> 繰り返す;繰り返して言う, 反復する</div><div class=\"ex\"><i>iterare agrum</i> (<author>C<small>IC</small></author>)<span class=\"ext\">再び耕す, 鋤き返す.</span></div><div class=\"def\"><num>②</num> 列挙する, 並べ立てる.</div><div class=\"def\"><num>③</num> 新たにする, 復活させる.</div><div class=\"def\"><num>④</num> 作りなおす.</div><div class=\"def\"><num>⑤</num> 再び訪れる.</div>\r\n","<div class=\"hw\">Ithaca</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">イタカ, <SUP>*</SUP>-ケー《イオニア海の島の一つ;Ulixes の故国と伝えられる》.</div>\r\n","<div class=\"hw\">Ithacensis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">Ithaca の.</div>\r\n","<div class=\"hw\">Ithacus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Ithaca の.</div><hr><div class=\"hw\">Ithacus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">Ithaca 人《特に Ulixes を指す》.</div>\r\n","<div class=\"hw\">Ithacēsius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Ithacensis\">Ithacensis</a>.</div>\r\n","<div class=\"hw\">itidem</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[ita;<i>cf. </i> idem]</div><div class=\"def\">同様に, 同じく.</div>\r\n","<div class=\"hw\">itineror</div><div class=\"pos\">-ārī, <SUP>◇</SUP><i>intr dep</i></div><div class=\"ori\">[iter]</div><div class=\"def\">旅をする.</div>\r\n","<div class=\"hw\">itinerārium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[↓<a href=\"entry://itinerārius\">itinerārius</a>]</div><div class=\"def\"><num>①</num> 旅行記.</div><div class=\"def\"><num>②</num> 出発[行進]の合図.</div>\r\n","<div class=\"hw\">itinerārius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[iter]</div><div class=\"def\"><num>①</num> 旅の.</div><div class=\"def\"><num>②</num> 旅程の.</div>\r\n","<div class=\"hw\">Itius portus</div><div class=\"pos\"><i>m</i></div><div class=\"def\">イティウス港《Gallia Belgica の港;ここから Caesar が Britannia へ渡った;現 Boulogne-sur-Mer または Wissant》.</div>\r\n","<div class=\"hw\">itiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[eo<SUP>2</SUP>]</div><div class=\"def\">行くこと.</div>\r\n","<div class=\"hw\">itus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://eō\">eo<SUP>2</SUP></a>.</div><hr><div class=\"hw\">itus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> 行くこと;歩み.</div><div class=\"def\"><num>②</num> 出発.</div>\r\n","<div class=\"hw\">Itys</div><div class=\"pos\">-yos, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙イテュス《Thracia の王 Tereus と Procne の息子;夫への復讐として母親に殺された》.</div>\r\n","<div class=\"hw\">itō<SUP>1</SUP></div><div class=\"pos\">-āre -āvī, <i>intr freq</i></div><div class=\"ori\">[eo<SUP>2</SUP>]</div><div class=\"def\">(頻繁に)行く.</div>\r\n","<div class=\"hw\">Itōnius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Itonus の.</div>\r\n","<div class=\"hw\">Itōnus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">イトーヌス, <SUP>*</SUP>-ノス《Boeotia の町;Athena の神殿があった》.</div>\r\n","<div class=\"hw\">Itōnē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">イトーネー《Thessalia の町;Athena の神殿があった》.</div>\r\n","<div class=\"hw\">Itūraea</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">Ituraei 族の国.</div>\r\n","<div class=\"hw\">Itūraeus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Ituraei 族の.</div>\r\n","<div class=\"hw\">Itūraeī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">イトゥーラエイー, <SUP>*</SUP>-ライオイ《Palaestina 北東部にいた一部族;弓矢に長けていたことで有名》.</div>\r\n","<div class=\"hw\">Ixīonidēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">〘伝説〙</div><div class=\"def\"><num>①</num> Ixion の息子(=<a href=\"entry://Pīrithous\">Pirithous</a>).</div><div class=\"def\"><num>②</num> (<i>pl</i> -dae)Ixion の子孫(=<a href=\"entry://Centaurus\">Centaurus</a> たち).</div>\r\n","<div class=\"hw\">Ixīonius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Ixion の.</div>\r\n","<div class=\"hw\">Ixīōn</div><div class=\"pos\">-onis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙イクシーオーン《Thessalia の Lapithae 族の王;Pirithous の父;Juno を犯そうとしたため, Juppiter により地獄の永遠に回る車輪に縛りつけられた》.</div>\r\n","<div class=\"hw\">iynx</div><div class=\"pos\">-ngis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘鳥〙アリスイ.</div>\r\n","<div class=\"hw\">Iālysius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Ialysus (3) の, Rhodos 島の.</div>\r\n","<div class=\"hw\">Iālysus</div><div class=\"pos\">-ī, <i>m</i>, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">イアーリュスス, <SUP>*</SUP>-ソス《 (1)(<i>m</i>)〘伝説〙太陽神 Sol の息子で (3) の創建者.(2)(<i>m</i>)Protogenes 作の (1) の肖像画.(3)(<i>f</i>)Rhodos 島の町》.</div>\r\n","<div class=\"hw\">Iāpydes</div><div class=\"pos\">-um, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">イアーピュデス《Illyria の一部族》.</div>\r\n","<div class=\"hw\">Iāpydia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">イアーピュディア《Iapydes 族の国》.</div>\r\n","<div class=\"hw\">Iāpygia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">イアーピュギア(ー)《Italia 半島南東部のギリシア語名》.</div>\r\n","<div class=\"hw\">Iāpygius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Iapygia の.</div>\r\n","<div class=\"hw\">Iāpys</div><div class=\"pos\">-ydis, <i>adj</i></div><div class=\"def\">Iapydia の.</div>\r\n","<div class=\"hw\">Iāpyx<SUP>1</SUP></div><div class=\"pos\">-ygis [-ygos], <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> イアーピュクス《 (1) 〘伝説〙Daedalus の息子;Italia 南部を支配した;Iapygia の名祖.(2) Apulia の川》.</div><div class=\"def\"><num>②</num> (Italia 半島南東部からギリシアの方向へ吹く)西北西の風.</div><hr><div class=\"hw\">Iāpyx<SUP>2</SUP></div><div class=\"pos\">-ygis [-ygos], <i>adj</i></div><div class=\"def\">=<a href=\"entry://Iāpygius\">Iapygius</a>.</div>\r\n","<div class=\"hw\">Iāsonius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Iason (1) の.</div>\r\n","<div class=\"hw\">Iāssensēs</div><div class=\"pos\">-ium, <i>m pl</i></div><div class=\"def\">Iasus の住民.</div>\r\n","<div class=\"hw\">Iāsus, Iassus</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">イアースス, <SUP>*</SUP>-ソス《Caria 西部の町》.</div>\r\n","<div class=\"hw\">Iāsō(n)</div><div class=\"pos\">-onis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">イアーソーン《 (1) 〘伝説〙Thessalia の王 Aeson の息子;Argonautae の首領;Medea の, のちに Creusa の夫.(2) Thessalia の Pherae の僭主(前4世紀)》.</div>\r\n","<div class=\"hw\">Iāzyges</div><div class=\"pos\">-um, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">イアージュゲス《Danubius 下流域にいた Sarmatae 族の一支族》.</div>\r\n","<div class=\"hw\">Iāzyx</div><div class=\"pos\">-ygis, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Iazyges 族の.</div>\r\n","<div class=\"hw\">Iēsūs</div><div class=\"pos\">-ū, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i><<i>Heb</i>.]</div><div class=\"def\">イエースース, <SUP>∥</SUP>イエス(キリスト).</div>\r\n","<div class=\"hw\">iī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://eō\">eo<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">iō</div><div class=\"pos\"><i>int</i></div><div class=\"def\"><num>①</num> (苦痛の叫び)ああ, おお.</div><div class=\"def\"><num>②</num> (喜びの叫び)万歳!</div><div class=\"def\"><num>③</num> (呼びかけ)おーい!</div>\r\n","<div class=\"hw\">Iōlciacus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Iolcus の.</div>\r\n","<div class=\"hw\">Iōlcus, -os</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">イーオルクス, <SUP>*</SUP>-コス《Thessalia の港町;ここから Argonautae が船出した》.</div>\r\n","<div class=\"hw\">Iōn</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙イオーン《Athenae 人で Xuthus の息子;Asia へ植民して Ionia 人の名祖となった》.</div>\r\n","<div class=\"hw\">Iōnes</div><div class=\"pos\">-um, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Ionia 人.</div>\r\n","<div class=\"hw\">Iōnia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">イオーニア(ー)《小アジアの西海岸, Caria と Aeolis の間の地域》.</div>\r\n","<div class=\"hw\">Iōniacus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Iōnicus\">Ionicus</a>.</div>\r\n","<div class=\"hw\">Iōnicos</div><div class=\"pos\">-ē -on, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Iōnicus\">Ionicus</a>.</div>\r\n","<div class=\"hw\">Iōnicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Ionia の, Ionia 人の.</div>\r\n","<div class=\"hw\">Iōnium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://Iōnius\">Iōnius</a>]</div><div class=\"def\">イオニア海(=mare Ionium).</div>\r\n","<div class=\"hw\">Iōnius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Ionia の, Ionia 人の.</div>\r\n","<div class=\"hw\">iōta</div><div class=\"pos\"><i>indecl n</i></div><div class=\"ori\">[<i>Gk</i><<i>Heb</i>.]</div><div class=\"def\">イオータ《ギリシア語アルファベットの第9字(Ι, ι)》.</div>\r\n","<div class=\"hw\">iūlis</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘魚〙ベラ.</div>\r\n","<div class=\"hw\">Iūlis</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">イウーリス《Cea 島の町;抒情詩人 Simonides と Bacchylides の生地;現 Zea》.</div>\r\n","<div class=\"hw\">iūlus, -os</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘植〙尾状花序, 花穂<SUB>かすい</SUB>.</div><div class=\"def\"><num>②</num> 〘動〙ワラジムシ.</div>\r\n","<div class=\"hw\">Iūlus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://Jūlus\">Julus</a>.</div>\r\n","<div class=\"hw\">Iūlēus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Jūlēus\">Juleus</a>.</div>\r\n","<div class=\"hw\">ī</div><div class=\"pos\">2 <i>sg impr pr</i></div><div class=\"def\">⇒<a href=\"entry://eō\">eo<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">īapetus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘神話〙イーアペトゥス, <SUP>*</SUP>-トス《Titanes の一人;Atlas, Prometheus, Epimetheus, Menoetius の父》.</div>\r\n","<div class=\"hw\">īapetīonidēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">Iapetus の息子(=<a href=\"entry://Atlās\">Atlas</a>).</div>\r\n","<div class=\"hw\">īasidēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">Iasius (2) の子孫《特に Adrastus》.</div>\r\n","<div class=\"hw\">īasis</div><div class=\"pos\">-idis [-idos], <i>f</i></div><div class=\"def\">Iasius (2) の娘(=<a href=\"entry://Atalanta\">Atalanta</a>).</div>\r\n","<div class=\"hw\">īasius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙イーアシウス, <SUP>*</SUP>-オス《 (1) Dardanus の兄弟;Ceres に愛されて Plutus の父となった.(2) Argos の王;Atalanta の父》.</div>\r\n","<div class=\"hw\">īasiōn</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">=<a href=\"entry://īasius\">Iasius (1)</a> .</div>\r\n","<div class=\"hw\">ībam</div><div class=\"pos\">1 <i>sg impf</i></div><div class=\"def\">⇒<a href=\"entry://eō\">eo<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">ībis</div><div class=\"pos\">-is [-idis], <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘鳥〙トキ科の鳥.</div>\r\n","<div class=\"hw\">ībycus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">イービュクス, <SUP>*</SUP>-コス《Regium (2) 生まれのギリシアの抒情詩人(前6世紀)》.</div>\r\n","<div class=\"hw\">ībō</div><div class=\"pos\">1 <i>sg fut</i></div><div class=\"def\">⇒<a href=\"entry://eō\">eo<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">īcadius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">イーカディウス, <SUP>*</SUP>-オス《有名な海賊の名》.</div>\r\n","<div class=\"hw\">īcaria</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">イーカリア(ー)《エーゲ海の島》.</div>\r\n","<div class=\"hw\">īcaris</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"def\">=<a href=\"entry://īcariōtis\">Icariotis<SUP>1</SUP></a>.</div>\r\n","<div class=\"hw\">īcarius<SUP>1</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙イーカリウス, <SUP>*</SUP>-オス《 (1) Sparta の王 Oebalus の息子で Penelope の父.(2) Athenae 人;Dionysus を歓待した礼にブドウの木を授けられ,隣人にぶどう酒を分け与えたが,毒を飲ませたと誤解され打ち殺された;死後 Bootes(牛飼い座)になった》.</div><hr><div class=\"hw\">īcarius<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Icarus (1)  (2) の.</div>\r\n","<div class=\"hw\">īcariōtis<SUP>1</SUP></div><div class=\"pos\">-idis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Icarius (1) の娘(=<a href=\"entry://Pēnelopē\">Penelope</a>).</div><hr><div class=\"hw\">īcariōtis<SUP>2</SUP></div><div class=\"pos\">-idis, <i>adj f</i></div><div class=\"def\">Icarius (1) の娘(Penelope)の.</div>\r\n","<div class=\"hw\">īcarus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙イーカルス, <SUP>*</SUP>-ロス《 (1) Daedalus の息子;父の造った蝋付けの翼で父とともに Creta 島から脱出したが, 太陽に接近しすぎたため蝋が溶け, 海に落ちて死んだ.(2) =<a href=\"entry://īcarius\">Icarius (2)</a> 》.</div>\r\n","<div class=\"hw\">īcas</div><div class=\"pos\">-adis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(毎月の)20日.</div>\r\n","<div class=\"hw\">īconicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">生き写しの, 等身大の.</div>\r\n","<div class=\"hw\">īconismus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[icon]</div><div class=\"def\">像[似姿]で表わすこと;特徴の表示.</div>\r\n","<div class=\"hw\">īconoclastēs</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">聖像[偶像]破壊者.</div>\r\n","<div class=\"hw\">īconographia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">図像法;図像学.</div>\r\n","<div class=\"hw\">īcī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://īcō\">ico</a>.</div>\r\n","<div class=\"hw\">īcō, īciō</div><div class=\"pos\">īcere īcī ictum, <i>tr</i></div><div class=\"def\">打つ, 打ち当てる</div><div class=\"ex\"><i>icere foedus</i> (<author>L<small>IV</small></author>)<span class=\"ext\">条約[協定]を結ぶ.</span></div>\r\n","<div class=\"hw\">īcōn</div><div class=\"pos\">-onis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 像, 画像;似姿.</div><div class=\"def\"><num>②</num> 聖画像, イコン.</div>\r\n","<div class=\"hw\">īda</div><div class=\"pos\">-ae, <B>-ē</B> -ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">イーダ(ー)《 (1) Creta 島の最高峰;Juppiter の生育地といわれる.(2) Phrygia の Troja 近くの山脈》.</div>\r\n","<div class=\"hw\">īdaeus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Ida 山の</div><div class=\"ex\"><i>～ puer</i> (<author>O<small>V</small></author>)<span class=\"ext\">=<a href=\"entry://Ganymēdēs\">Ganymedes</a></span></div><div class=\"ex\"><i>～ judex</i> (<author>O<small>V</small></author>)<span class=\"ext\">=<a href=\"entry://Paris\">Paris</a></span></div><div class=\"ex\"><i>Idaea mater [parens]</i> (<author>C<small>IC</small> [O<small>V</small>]</author>)<span class=\"ext\">=<a href=\"entry://Cybelē\">Cybele</a>.</span></div>\r\n","<div class=\"hw\">īdalia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">=<a href=\"entry://īdalium\">Idalium</a>.</div>\r\n","<div class=\"hw\">īdalium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">イーダリウム, <SUP>*</SUP>-オン《Cyprus 島の山と町;Venus の神殿があった》.</div>\r\n","<div class=\"hw\">īdalius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Idalium の.</div>\r\n","<div class=\"hw\">īdaliē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Idalium の女神《Venus の添え名》.</div>\r\n","<div class=\"hw\">īdem</div><div class=\"pos\">eadem idem, <i>pron</i>, <i>adj demonstr</i></div><div class=\"ori\">[is/-dem]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>adj</i>)同じ, 同一の, 同様の.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>pron</i>)同じ人[もの], 同様のもの</div><div class=\"ex\"><i>～ ac [atque, et, ut, quasi]</i><span class=\"ext\">...と同じもの</span></div><div class=\"ex\"><i>amicus est tamquam alter ～</i> (<author>C<small>IC</small></author>)<span class=\"ext\">友とはいわば第二の自己だ</span></div><div class=\"ex\"><i>viros fortes, magnanimos, eosdem bonos et simplices esse volumus</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私たちは強くて度量のある人たちが同時に善良で誠実であることを望む</span></div><div class=\"ex\"><i>me memorderunt epistulae tuae de Attica nostra</i>;<i>eaedem tamen sanaverunt</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私たちの Attica についてのあなたの手紙は私の心を突き刺したけれども, またその傷をいやしてくれた.</span></div>\r\n","<div class=\"hw\">īdib.</div><div class=\"def\">《略》=Idibus(<i>abl</i>;⇒ <a href=\"entry://īdūs\">Idus</a>).</div>\r\n","<div class=\"hw\">īdomeneus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙イードメネウス《Creta 島の王;Troja 戦争におけるギリシア軍の勇将の一人》.</div>\r\n","<div class=\"hw\">īdos</div><div class=\"pos\"><i>indecl n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">姿, 外観(=<a href=\"entry://speciēs\">species</a>).</div>\r\n","<div class=\"hw\">īdyllium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">田園詩, 牧歌.</div>\r\n","<div class=\"hw\">īdās</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙イーダース《Argonautae の一人;Aphareus の息子で Lynceus の兄弟;Euenus の娘 Marpessa を Apollo と争った》.</div>\r\n","<div class=\"hw\">īdē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"def\">=<a href=\"entry://īda\">Ida</a>.</div>\r\n","<div class=\"hw\">īdōlicus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">偶像(崇拝)の.</div>\r\n","<div class=\"hw\">īdōlolatra, -ēs</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">偶像崇拝者, 異教徒.</div>\r\n","<div class=\"hw\">īdōlolatris</div><div class=\"pos\">-idis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">偶像崇拝者《女性》.</div>\r\n","<div class=\"hw\">īdōlolatrīa</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">偶像崇拝.</div>\r\n","<div class=\"hw\">īdōlothytus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">偶像への供え物の.</div>\r\n","<div class=\"hw\">īdōlum, -on</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 亡霊, 幽霊.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 偶像.</div>\r\n","<div class=\"hw\">īdōlēum, -īum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">偶像をまつる神殿.</div>\r\n","<div class=\"hw\">īdūs</div><div class=\"pos\">-uum, <i>f pl</i></div><div class=\"def\">(3・5・7・10月の)15日;(その他の月の)13日</div><div class=\"ex\"><i>～ Martiae</i> (<author>C<small>IC</small></author>)<span class=\"ext\">3月15日.</span></div>\r\n","<div class=\"hw\">īguvium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">イーグウィウム《Umbria 中部の町;現 Gubbio》.</div>\r\n","<div class=\"hw\">īguvīnātēs</div><div class=\"pos\">-ium, <i>m pl</i></div><div class=\"def\">=<a href=\"entry://īguvīnī\">Iguvini</a>.</div>\r\n","<div class=\"hw\">īguvīnī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">Iguvium の住民.</div>\r\n","<div class=\"hw\">īle</div><div class=\"pos\">-is, <i>n</i></div><div class=\"def\">⇒<a href=\"entry://īlia\">ilia</a>.</div>\r\n","<div class=\"hw\">īleocōlicus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解〙回結腸の.</div>\r\n","<div class=\"hw\">īleos, -us</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘病〙腸閉塞(症).</div>\r\n","<div class=\"hw\">īleum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘解〙回腸.</div>\r\n","<div class=\"hw\">īlex</div><div class=\"pos\">īlicis, <i>f</i></div><div class=\"def\">〘植〙トキワガシ.</div>\r\n","<div class=\"hw\">īlia</div><div class=\"pos\">īlium, <i>n pl</i></div><div class=\"def\"><num>①</num> (一番下の肋骨から鼠蹊部までの)腹部, わき腹.</div><div class=\"def\"><num>②</num> 鼠蹊<SUB>そけい</SUB>部.</div><div class=\"def\"><num>③</num> (動物の)はらわた.</div><hr><div class=\"hw\">īlia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">イーリア《Numitor の娘で Romulus と Remus の母;=<a href=\"entry://Rhēa Silvia\">Rhea Silvia</a>》.</div>\r\n","<div class=\"hw\">īliacosubfasciālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解〙腸骨筋膜下の.</div>\r\n","<div class=\"hw\">īliacus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Ilium の.</div>\r\n","<div class=\"hw\">īliadēs<SUP>1</SUP></div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">〘伝説〙Ilia の息子(=<a href=\"entry://Rōmulus\">Romulus</a> または <a href=\"entry://Remus\">Remus</a>).</div><hr><div class=\"hw\">īliadēs<SUP>2</SUP></div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">〘伝説〙Ilium(=<a href=\"entry://Trōja\">Troja</a>)人《特に Ganymedes》.</div>\r\n","<div class=\"hw\">īlias</div><div class=\"pos\">-adis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> Ilium(=<a href=\"entry://Trōja\">Troja</a>)の女(=<a href=\"entry://Helena\">Helena</a>).</div><div class=\"def\"><num>②</num> イーリアス《Homerus 作と伝えられる英雄叙事詩》.</div>\r\n","<div class=\"hw\">īlicet</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[ire/licet]</div><div class=\"def\"><num>①</num> 行ってもよい, 去れ.</div><div class=\"def\"><num>②</num> 万事休す, もうだめだ.</div><div class=\"def\"><num>③</num> 直ちに, 即座に.</div>\r\n","<div class=\"hw\">īliceus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ilex]</div><div class=\"def\">トキワガシの.</div>\r\n","<div class=\"hw\">īlicētum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[ilex]</div><div class=\"def\">トキワガシの森.</div>\r\n","<div class=\"hw\">īlicō</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[in/locus]</div><div class=\"def\"><num>①</num> その場で, 現場で.</div><div class=\"def\"><num>②</num> 直ちに, 即刻.</div>\r\n","<div class=\"hw\">īliensēs</div><div class=\"pos\">-ium, <i>m pl</i></div><div class=\"def\"><num>①</num> イーリエンセース《Sardinia 島にいた一部族》.</div><div class=\"def\"><num>②</num> Ilium(=<a href=\"entry://Trōja\">Troja</a>)の住民.</div>\r\n","<div class=\"hw\">īlignus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ilex]</div><div class=\"def\">トキワガシの.</div>\r\n","<div class=\"hw\">īliofemorālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解〙腸骨大腿骨の.</div>\r\n","<div class=\"hw\">īliona</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙イーリオナ, <SUP>*</SUP>-ネー《Troja の王 Priamus と Hecuba の長女;Thracia の王 Polymestor の妻》.</div>\r\n","<div class=\"hw\">īlioneus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙イーリオネウス《 (1) Niobe と Amphion の末子.(2) Troja 人 Phorbas の息子;Aeneas の部下》.</div>\r\n","<div class=\"hw\">īlios</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"def\">=<a href=\"entry://īlium\">Ilium</a>.</div>\r\n","<div class=\"hw\">īlium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘解〙腸骨.</div><hr><div class=\"hw\">īlium, -on</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">イーリウム, <SUP>*</SUP>-オン《Troja の詩的名称》.</div>\r\n","<div class=\"hw\">īlius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Ilium(=<a href=\"entry://Trōja\">Troja</a>)の.</div>\r\n","<div class=\"hw\">īlus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙イールス, <SUP>*</SUP>-ロス《 (1) Tros の息子で Assaracus と Ganymedes の兄弟;Laomedon の父;Ilium の創建者.(2) =<a href=\"entry://Jūlus\">Julus</a>》.</div>\r\n","<div class=\"hw\">īlīthyia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘神話〙イーリーテュイア, <SUP>*</SUP>エイレイ-《ギリシアの出産をつかさどる女神;ローマ神話の Lucina に当たる》.</div>\r\n","<div class=\"hw\">īlōtae</div><div class=\"pos\">-ārum, <i>m pl</i></div><div class=\"def\">=<a href=\"entry://Hīlōtae\">Hilotae</a>.</div>\r\n","<div class=\"hw\">īmitus</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[imus]</div><div class=\"def\">底から, 底で.</div>\r\n","<div class=\"hw\">īmulus</div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[imus]</div><div class=\"def\">一番下の.</div>\r\n","<div class=\"hw\">īmum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://īmus\">īmus</a>]</div><div class=\"def\"><num>①</num> 最低[下]部, 底, 最深部;冥界.</div><div class=\"def\"><num>②</num> 最後.</div>\r\n","<div class=\"hw\">īmus</div><div class=\"pos\">-a -um, <i>adj superl</i></div><div class=\"def\"><num>①</num> 最低の, 最下部の, 底の;冥界の.</div><div class=\"def\"><num>②</num> 最低音の.</div><div class=\"def\"><num>③</num> (社会的に)最下層の.</div><div class=\"def\"><num>④</num> 最後[最終]の.</div>\r\n","<div class=\"hw\">īmō</div><div class=\"pos\"><i>adv</i></div><div class=\"def\">=<a href=\"entry://immō\">immo</a>.</div>\r\n","<div class=\"hw\">īna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">パピルス紙の繊維.</div>\r\n","<div class=\"hw\">īnachidēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Inachus の子孫(=<a href=\"entry://Epaphus\">Epaphus</a>, <a href=\"entry://Perseus\">Perseus</a>).</div>\r\n","<div class=\"hw\">īnachis<SUP>1</SUP></div><div class=\"pos\">-idis, <i>adj f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Inachus の.</div><hr><div class=\"hw\">īnachis<SUP>2</SUP></div><div class=\"pos\">-idis [-idos], <i>f</i></div><div class=\"def\">Inachus の娘(=<a href=\"entry://īō\">Io</a>).</div>\r\n","<div class=\"hw\">īnachius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> Inachus の.</div><div class=\"def\"><num>②</num> 《詩》Argos の, ギリシアの.</div>\r\n","<div class=\"hw\">īnachus<SUP>1</SUP>, -os</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘神話〙イーナクス, <SUP>*</SUP>-コス《Argolis の川;その河神で Io の父;Argos の初代の王ともいわれる》.</div><hr><div class=\"hw\">īnachus<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://īnachius\">Inachius</a>.</div>\r\n","<div class=\"hw\">īnarimē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"def\">イーナリメー《Campania 沖の火山島 Aenaria または Pithecusae の詩的名称》.</div>\r\n","<div class=\"hw\">īnuleus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://hinnuleus\">hinnuleus</a>.</div>\r\n","<div class=\"hw\">īnō</div><div class=\"pos\">-ūs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘神話〙イーノー《Cadmus と Harmonia の娘;Thessalia の王 Athamas の後妻;夫からのがれて息子 Melicerta とともに海に投身し, 海の女神 Leucothea となった》.</div>\r\n","<div class=\"hw\">īnōus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Ino の.</div>\r\n","<div class=\"hw\">īphias</div><div class=\"pos\">-adis, <i>f</i></div><div class=\"def\">Iphis の娘(=<a href=\"entry://Euadnē\">Euadne</a>).</div>\r\n","<div class=\"hw\">īphiclus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙イーピクルス, <SUP>*</SUP>-ロス《Argonautae の一人;足が速いので有名》.</div>\r\n","<div class=\"hw\">īphicratensis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">Iphicrates の.</div>\r\n","<div class=\"hw\">īphicratēs</div><div class=\"pos\">-īs, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">イーピクラテース《Athenae の将軍(前415?‐?353)》.</div>\r\n","<div class=\"hw\">īphigenīa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙イーピゲニーア, <SUP>*</SUP>-ネイア《Agamemnon と Clytaemnestra の娘;Aulis で Diana の犠牲にされようとしたとき女神に助けられてその巫女となった》.</div>\r\n","<div class=\"hw\">īphis<SUP>1</SUP></div><div class=\"pos\">-is, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙イーピス《Cyprus 島の青年;Anaxarete への恋がかなわなかったため自殺した》.</div><hr><div class=\"hw\">īphis<SUP>2</SUP></div><div class=\"pos\">-idis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙イーピス《Creta 島の Ligdus の娘;男に変えられた》.</div>\r\n","<div class=\"hw\">īphitidēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">〘伝説〙Iphitus の息子(=<a href=\"entry://Coeranus\">Coeranus</a>).</div>\r\n","<div class=\"hw\">īphitus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙イーピトゥス, <SUP>*</SUP>-トス《Oechalia の王 Eurytus の息子;Argonautae の一人》.</div>\r\n","<div class=\"hw\">īra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 怒り, 憤り.</div><div class=\"def\"><num>②</num> 敵意, 憎しみ.</div><div class=\"def\"><num>③</num> 憤りの原因.</div><div class=\"def\"><num>④</num> (自然の力の)猛威.</div>\r\n","<div class=\"hw\">īrascentia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[irascor]</div><div class=\"def\">=<a href=\"entry://īrācundia\">iracundia</a>.</div>\r\n","<div class=\"hw\">īrascor</div><div class=\"pos\">-scī īrātus sum, <i>intr dep</i></div><div class=\"ori\">[iratus]</div><div class=\"def\">怒(ってい)る, 憤(ってい)る 〈+<i>dat</i>〉.</div>\r\n","<div class=\"hw\">īrascī</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://īrascor\">irascor</a>.</div>\r\n","<div class=\"hw\">īre</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://eō\">eo<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">īris</div><div class=\"pos\">-idis [-is], <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 虹.</div><div class=\"def\"><num>②</num> (I-)〘神話〙イーリス《虹の女神で神々の使者》.</div><div class=\"def\"><num>③</num> 〘植〙アヤメ属の植物;イリスの根《香料用・薬用》.</div><div class=\"def\"><num>④</num> 〘鉱〙アイリス《虹色の水晶》.</div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP>〘解〙(眼球の)虹彩.</div>\r\n","<div class=\"hw\">īrus, -os</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙イールス, <SUP>*</SUP>-ロス《Ithaca 島の Ulixes の家にいた乞食》.</div>\r\n","<div class=\"hw\">īrācundia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[iracundus]</div><div class=\"def\"><num>①</num> 短気, 激しやすいこと.</div><div class=\"def\"><num>②</num> 怒り, 憤り.</div>\r\n","<div class=\"hw\">īrācunditer</div><div class=\"pos\"><i>adv</i></div><div class=\"def\">=<a href=\"entry://īrācundē\">iracunde</a>.</div>\r\n","<div class=\"hw\">īrācundus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ira]</div><div class=\"def\"><num>①</num> 短気な, 激しやすい.</div><div class=\"def\"><num>②</num> 憤った, 怒った.</div>\r\n","<div class=\"hw\">īrācundē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[iracundus]</div><div class=\"def\">憤って, 怒って.</div>\r\n","<div class=\"hw\">īrātus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://īrascor\">irascor</a>.</div><hr><div class=\"hw\">īrātus<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ira]</div><div class=\"def\">怒った, 憤った 〈+<i>dat</i>;de re〉.</div>\r\n","<div class=\"hw\">īrātē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[iratus<SUP>2</SUP>]</div><div class=\"def\">怒って, 憤って.</div>\r\n","<div class=\"hw\">īrī</div><div class=\"pos\"><i>pass inf pr</i></div><div class=\"def\">⇒<a href=\"entry://eō\">eo<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">īrōnicus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">反語的な, 皮肉な.</div>\r\n","<div class=\"hw\">īrōnicē</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[ironicus]</div><div class=\"def\">からかって, 皮肉に.</div>\r\n","<div class=\"hw\">īrōnicōs</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">=<a href=\"entry://īrōnicē\">ironice</a>.</div>\r\n","<div class=\"hw\">īrōnīa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">反語, あてこすり, 皮肉.</div>\r\n","<div class=\"hw\">īsaeus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">イーサエウス, <SUP>*</SUP>-サイオス《Athenae の弁論家(前420?‐?345);Demosthenes の師》.</div>\r\n","<div class=\"hw\">īsagōga</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">手引き, 序説.</div>\r\n","<div class=\"hw\">īselasticum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://īselasticus\">īselasticus</a>]</div><div class=\"def\">ギリシアの四大競技会の勝利者に与えられるローマ皇帝の褒賞.</div>\r\n","<div class=\"hw\">īselasticus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><i>certamen iselasticum</i> (<author>P<small>LIN</small> M<small>IN</small></author>) iselasticum が与えられる競技会《その勝利者は故郷への凱旋行進を許された》.</div>\r\n","<div class=\"hw\">īsiacus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Isis の.</div>\r\n","<div class=\"hw\">īsidium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘植〙裂芽.</div>\r\n","<div class=\"hw\">īsis</div><div class=\"pos\">-is [-idis], <i>f</i></div><div class=\"ori\">[<i>Gk</i><<i>Egypt</i>.]</div><div class=\"def\">〘神話〙イーシス《エジプトの女神;Osiris の妻》.</div>\r\n","<div class=\"hw\">īsocratēs</div><div class=\"pos\">-is, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">イーソクラテース《Athenae の雄弁家・修辞家(前436‐338)》.</div>\r\n","<div class=\"hw\">īsocratēus, -tīus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Isocrates の.</div>\r\n","<div class=\"hw\">ītō<SUP>2</SUP></div><div class=\"pos\">2 & 3 <i>sg impr fut</i></div><div class=\"def\">⇒<a href=\"entry://eō\">eo<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">īvī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://eō\">eo<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">īātralipticē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">マッサージ療法.</div>\r\n","<div class=\"hw\">īātraliptēs, -a</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">マッサージ師.</div>\r\n","<div class=\"hw\">īātronīcēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">医師たちの征服者(=医者の中の医者).</div>\r\n","<div class=\"hw\">īō</div><div class=\"pos\">(<i>dat</i> īōnī, <i>acc</i> īō [īōn], <i>abl</i> īō), <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘神話〙イーオー《Argolis の河神 Inachus の娘;Juppiter に愛され, Juno のねたみを恐れた Juppiter が彼女を白い雌牛に変えた》.</div>\r\n"]);
